// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 _changeFee, uint16 _feeRate, address _nft, address _baseToken) public {
        _feeRate = uint16(bound(_feeRate, 0, 5000));

        uint128 _vBase = uint128(1);
        uint128 _vNft = uint128(1);
        bytes32 _merkle = bytes32(0);
        bool _useOracle = false;
        bool _payRoyalties = false;

        bool ok;
        try c.initialize(_baseToken, _nft, _vBase, _vNft, _changeFee, _feeRate, _merkle, _useOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.changeFee() == _changeFee);
        } else {
            assertTrue(!c.initialized());
        }
    }
}
